# This code has been fully generated by an AI.
"""Tracking in der entzerrten Arena: Vorschlag, Start, Verfolgung, Re-ID und EdgeTAM nebenher."""

import time

import cv2
import numpy as np
import pytest

from hebocon.tracking import (
    LOST_AFTER_S,
    NO_LOGIT,
    REID_EVERY,
    STABLE_FRAMES,
    Arbiter,
    Track,
    Tracker,
    exclusive,
    keep_group,
    plausible,
    should_swap,
)

from .conftest import ROBOT_COLOR, H, W, scene

SQUARE = (220, 200)
TRIANGLE = (420, 300)


def units(arena, p):
    """Kamerapunkt in Arena-Einheiten."""
    return cv2.perspectiveTransform(np.array([[p]], np.float32), arena.h)[0, 0]


def settle(tracker, image, seeds=None):
    for _ in range(STABLE_FRAMES):
        picks = tracker.propose(image, seeds or {})
    return picks


def make(arena, arbiter=None):
    tracker = Tracker(arena)
    settle(tracker, scene(square=SQUARE, triangle=TRIANGLE))
    tracker.start(["Kiste", "Keil"], arbiter, 0.0)
    return tracker


def by_id(robots):
    return {r.id: r for r in robots}


def test_exclusive_gives_each_pixel_one_owner():
    logits = np.array([[[5.0, -1.0]], [[2.0, 3.0]]])
    out = exclusive(logits)
    assert out[0, 0, 0] == 5.0 and out[1, 0, 0] == NO_LOGIT
    assert out[0, 0, 1] == NO_LOGIT and out[1, 0, 1] == 3.0
    assert np.array_equal(exclusive(logits[:1]), logits[:1])


def test_keep_group_drops_detached_hand():
    robot = np.zeros((64, 64), bool)
    robot[10:20, 10:20] = True
    wheel = np.zeros_like(robot)
    wheel[10:20, 22:25] = True
    hand = np.zeros_like(robot)
    hand[40:60, 40:60] = True
    out = keep_group(robot | wheel | hand, prev=robot)
    assert out[15, 15] and out[15, 23] and not out[50, 50]
    assert keep_group(robot | hand, prev=None)[50, 50]


def test_plausible_area_window():
    assert plausible(100, 100) and plausible(55, 100) and plausible(150, 100)
    assert not plausible(40, 100) and not plausible(170, 100)


def test_swap_only_when_both_clearly_flipped():
    assert should_swap(np.array([[0.5, 0.9], [0.9, 0.5]]))
    assert not should_swap(np.array([[0.9, 0.5], [0.5, 0.9]]))
    assert not should_swap(np.array([[0.5, 0.9], [0.5, 0.9]]))
    assert not should_swap(np.array([[0.80, 0.82], [0.82, 0.80]]))


# ---------- Vorschlag ----------


def test_propose_finds_both_left_first(arena):
    tracker = Tracker(arena)
    picks = settle(tracker, scene(square=SQUARE, triangle=TRIANGLE))
    cx = [tracker.outline(m)[:, 0].mean() for m in picks]
    assert cx[0] < cx[1]


def test_propose_is_stable_when_robots_pass_each_other(arena):
    tracker = Tracker(arena)
    settle(tracker, scene(square=(250, 200), triangle=(400, 330)))
    # Der Linke fährt nach rechts hinüber; die Nummer bleibt beim selben Roboter.
    for x in range(250, 520, 10):
        picks = tracker.propose(scene(square=(x, 200), triangle=(400, 330)), {})
    first = tracker.outline(picks[0])
    assert first[:, 0].mean() > units(arena, (420, 200))[0]


def test_click_assigns_slot(arena):
    tracker = Tracker(arena)
    tri = units(arena, TRIANGLE)
    picks = settle(tracker, scene(square=SQUARE, triangle=TRIANGLE), {0: tuple(tri)})
    assert abs(tracker.outline(picks[0])[:, 0].mean() - tri[0]) < 30


def test_click_splits_touching_robots(arena):
    tracker = Tracker(arena)
    image = scene()
    cv2.rectangle(image, (250, 250), (300, 300), ROBOT_COLOR, -1)
    cv2.rectangle(image, (300, 250), (350, 300), (40, 40, 160), -1)
    seeds = {0: tuple(units(arena, (270, 275))), 1: tuple(units(arena, (330, 275)))}
    picks = settle(tracker, image, seeds)
    assert all(p is not None and p.any() for p in picks)
    assert not (picks[0] & picks[1]).any()
    assert tracker.outline(picks[0])[:, 0].mean() < tracker.outline(picks[1])[:, 0].mean()


def test_start_needs_both(arena):
    tracker = Tracker(arena)
    settle(tracker, scene(square=SQUARE))
    with pytest.raises(ValueError):
        tracker.start(["A", "B"], None, 0.0)


def test_ignores_things_outside_arena(arena):
    tracker = Tracker(arena)
    image = scene(square=SQUARE, triangle=TRIANGLE)
    image[200:260, 10:60] = 0
    assert len(tracker._groups(tracker.foreground(tracker.view(image)))) == 2


# ---------- Kampf ----------


def test_tracker_follows_motion(arena):
    tracker = make(arena)
    t = 0.0
    for i in range(1, 11):
        t += 0.1
        robots, contact = tracker.update(scene(square=(220 + 5 * i, 200), triangle=TRIANGLE), t)
    robots = by_id(robots)
    assert not contact and robots[1].present and robots[2].present
    # Mehrheitsfilter: ein Bild Verzögerung.
    assert abs(robots[1].pos[0] - units(arena, (265, 200))[0]) < 15
    assert robots[1].vel[0] > 0 and abs(robots[2].vel[0]) < 5
    assert robots[1].inside == 1.0


def test_contact_and_ringout(arena):
    tracker = make(arena)
    t, x = 0.0, TRIANGLE[0]
    contact = False
    while x > 340 and not contact:
        x -= 5
        t += 0.05
        _, contact = tracker.update(scene(square=(300, 300), triangle=(x, 300)), t)
    assert contact
    for sx in range(300, 75, -5):
        t += 0.05
        robots, contact = tracker.update(scene(square=(sx, 300), triangle=(420, 300)), t)
    robots = by_id(robots)
    assert not contact
    # Linker Rand liegt bei y 300 etwa bei x 87: knapp die Hälfte ist draußen.
    assert robots[1].edge and 0.2 < robots[1].inside < 0.8


def test_drops_after_loss(arena):
    tracker = make(arena)
    t = 0.0
    for _ in range(STABLE_FRAMES):
        t += 0.1
        tracker.update(scene(triangle=TRIANGLE), t)
    robots, _ = tracker.update(scene(triangle=TRIANGLE), t + LOST_AFTER_S)
    robots = by_id(robots)
    assert not robots[1].present and robots[2].present


def test_contour_area_matches(arena):
    tracker = make(arena)
    square = [(195, 175), (245, 175), (245, 225), (195, 225)]
    expected = cv2.contourArea(np.array([units(arena, p) for p in square], np.float32))
    got = cv2.contourArea(tracker.slots[0].outline.reshape(-1, 1, 2))
    assert abs(got - expected) / expected < 0.2


def test_fully_out_leaves_at_edge(arena):
    tracker = make(arena)
    t = 0.0
    for x in range(420, 0, -10):
        t += 0.05
        tracker.update(scene(square=SQUARE, triangle=(x, 300)), t)
    t += LOST_AFTER_S
    robots, _ = tracker.update(scene(square=SQUARE), t)
    gone = by_id(robots)[2]
    assert not gone.present and gone.edge


def test_reid_fixes_swapped_identity(arena):
    tracker = make(arena)
    tracker.update(scene(square=SQUARE, triangle=TRIANGLE), 0.1)
    tracker._swap()
    t = 0.1
    for _ in range(REID_EVERY):
        t += 0.05
        tracker.update(scene(square=SQUARE, triangle=TRIANGLE), t)
    assert {s.id: s.name for s in tracker.slots} == {1: "Kiste", 2: "Keil"}
    assert min(tracker.slots, key=lambda s: s.c[0]).id == 1


class Scripted:
    """Ein Videomodell, das jeden Roboter richtig erkennt; Masken in der Draufsicht wie bei EdgeTAM."""

    def __init__(self, tracker):
        self.tracker = tracker
        self.added: list[int] = []
        self.calls = 0

    def reset_tracking(self):
        self.added.clear()

    def add_object(self, obj_id, bgr, box, points):
        self.added.append(obj_id)

    def track(self, bgr):
        self.calls += 1
        out = {}
        for i, kw in ((1, {"square": SQUARE}), (2, {"triangle": TRIANGLE})):
            img = scene(**kw)
            mask = (img == ROBOT_COLOR).all(2).astype(np.uint8) * 255
            out[i] = Track(self.tracker.view(cv2.merge([mask] * 3))[..., 0] > 127, True)
        return out


def test_arbiter_corrects_identity(arena, monkeypatch):
    model = Scripted(Tracker(arena))
    tracker = make(arena, Arbiter(model, lambda image: image))
    assert model.added == [1, 2]
    # Re-ID aus, damit nur EdgeTAM den Fehler finden kann.
    monkeypatch.setattr(tracker, "_check", lambda view: None)
    image = scene(square=SQUARE, triangle=TRIANGLE)
    tracker.update(image, 0.1)
    tracker._swap()
    t, deadline = 0.1, time.monotonic() + 5
    while tracker.corrections == 0 and time.monotonic() < deadline:
        t += 0.05
        tracker.update(image, t)
        time.sleep(0.01)
    tracker.close()
    assert tracker.corrections >= 1 and model.calls >= 1
    square_slot = min(tracker.slots, key=lambda s: s.c[0])
    assert square_slot.id == 1 and square_slot.name == "Kiste"


def test_view_has_tracker_size(arena):
    tracker = Tracker(arena)
    w, h = tracker.size
    assert tracker.view(np.zeros((H, W, 3), np.uint8)).shape[:2] == (h, w)
